using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Racer;using Object=UnityEngine.Object;
public static class CaveFlightClearance{public static string Main(){EditorSceneManager.OpenScene("Assets/Scenes/LakeWoods.unity");var b=Object.FindObjectsByType<WoodlandRoute>().Single(x=>x.title=="Echo Cave");var mf=GameObject.Find("Echo Cave enclosed rock").GetComponent<MeshFilter>();var src=mf.sharedMesh;var v=src.vertices;for(int i=0;i<v.Length;i++){float s=b.Project(v[i],out _);if(s<340||s>465)continue;var p=b.At(s,out _);float oldHeight=v[i].y-p.y;float factor=Mathf.SmoothStep(0,1,Mathf.InverseLerp(340,360,s))*(1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(445,465,s)));float crown=Mathf.Max(b.At(s-30,out _).y,b.At(s+30,out _).y,p.y)+14;float lift=Mathf.Max(0,crown-(p.y+7));v[i].y+=lift*factor*Mathf.Clamp01((oldHeight+.25f)/7);}
var m=Object.Instantiate(src);m.vertices=v;m.RecalculateNormals();m.RecalculateBounds();AssetDatabase.CreateAsset(m,"Assets/Track/SevenCorrections/Cave flight chamber.asset");mf.sharedMesh=m;mf.GetComponent<MeshCollider>().sharedMesh=m;
// Keep the existing visible gap open and remove formations from its airborne clearance.
foreach(var t in mf.transform.parent.Cast<Transform>().Where(t=>t.name=="Hanging angular cave formation"||t.name=="Exposed ceiling root"||t.name=="Shallow cave puddle"||t.name=="Cave gravel floor patch").ToArray()){float s=b.Project(t.position,out _);if((s>350&&s<455&&(t.name.Contains("formation")||t.name.Contains("root")))||(s>385&&s<402))Object.DestroyImmediate(t.gameObject);}
var floor=GameObject.Find("Cave natural gravel floor").GetComponent<MeshFilter>();m=Object.Instantiate(floor.sharedMesh);var fv=m.vertices;var tr=m.triangles;var keep=new List<int>();for(int i=0;i<tr.Length;i+=3){float s=b.Project((fv[tr[i]]+fv[tr[i+1]]+fv[tr[i+2]])/3,out _);if(s>385&&s<402)continue;keep.AddRange(new[]{tr[i],tr[i+1],tr[i+2]});}m.triangles=keep.ToArray();AssetDatabase.CreateAsset(m,"Assets/Track/SevenCorrections/Cave gravel preserves gap.asset");floor.sharedMesh=m;
EditorSceneManager.MarkSceneDirty(mf.gameObject.scene);EditorSceneManager.SaveScene(mf.gameObject.scene);AssetDatabase.SaveAssets();File.WriteAllText("Docs/SevenCorrections/cave-clearance.txt","Existing cave takeoff is station387, gap ends399. Raised natural flight chamber at340-465 to preserve original max-neighbour clearance; removed hanging detail and floor overlays across flight. No floor collision/route/gates moved.");return "Existing cave flight clearance preserved";}}
